"""Transport, authentication, typed failures, cursor pagination and MCP tool calls shared by every component client. Generated by scripts/sdks/python.py from contracts/http; do not edit."""
from __future__ import annotations

from dataclasses import dataclass, fields, is_dataclass
import itertools
import json
from typing import Any, Callable, Iterator, Literal, Optional
from urllib.error import HTTPError
from urllib.parse import quote, urlencode
from urllib.request import Request, urlopen

ProblemKind = Literal["validation_error", "authentication_required", "permission_denied", "not_found", "conflict", "quota_exceeded", "rate_limited", "temporarily_unavailable", "provider_unavailable", "internal_error", "revision_conflict", "output_contract_error"]


@dataclass(frozen=True)
class Auth:
    """Both credentials are sent as `Authorization: Bearer`; the server tells them apart."""
    kind: Literal["personalSession", "integrationKey"]
    secret: str

    @staticmethod
    def personal_session(token: str) -> "Auth":
        """A personal merchant session from `identity.post_auth_login` or `identity.post_auth_register`."""
        return Auth("personalSession", token)

    @staticmethod
    def integration_key(key: str) -> "Auth":
        """A scoped integration key from `identity.post_workspace_integrations`. Keep it server-side."""
        return Auth("integrationKey", key)


@dataclass(frozen=True)
class Problem:
    """One entry of the `{"errors":[...]}` envelope every HTTP failure and MCP tool error carries."""
    kind: str
    retryable: bool
    code: str
    status: int
    detail: str
    scope: Optional[str] = None
    pointer: Optional[str] = None
    current_revision: Optional[int] = None

    @staticmethod
    def parse(value: dict) -> "Problem":
        return Problem(**{f.name: value.get(_CAMEL[f.name]) for f in fields(Problem)})


_CAMEL = {"kind": "kind", "retryable": "retryable", "scope": "scope", "pointer": "pointer", "current_revision": "currentRevision", "code": "code", "status": "status", "detail": "detail"}


def _problems(body: Any) -> list[Problem]:
    errors = body.get("errors") if isinstance(body, dict) else None
    return [Problem.parse(e) for e in errors if isinstance(e, dict)] if isinstance(errors, list) else []


class VeyndoError(Exception):
    """An HTTP or MCP tool failure with the server's structured problems."""

    def __init__(self, status: int, problems: list[Problem], body: Any):
        super().__init__(problems[0].detail if problems else f"Veyndo request failed with HTTP {status}")
        self.status = status
        self.problems = problems
        self.body = body

    @property
    def kind(self) -> Optional[str]:
        return self.problems[0].kind if self.problems else None

    @property
    def retryable(self) -> bool:
        return any(p.retryable for p in self.problems)


class McpProtocolError(Exception):
    """A JSON-RPC protocol error from `/mcp` (unknown tool, malformed call)."""

    def __init__(self, code: int, message: str, data: Any = None):
        super().__init__(message)
        self.code = code
        self.data = data


def encode(value: Any) -> Any:
    """Dataclass tool inputs -> JSON values: absent optional fields are omitted, `extra` is merged."""
    if is_dataclass(value) and not isinstance(value, type):
        out: dict[str, Any] = {}
        for f in fields(value):
            item = getattr(value, f.name)
            if f.metadata.get("extra"):
                out.update({k: encode(v) for k, v in item.items()})
            elif item is not None or f.default is not None:
                # Optional fields default to None and are omitted; a required nullable field sends null.
                out[f.metadata.get("json", f.name)] = encode(item)
        return out
    if isinstance(value, (list, tuple)):
        return [encode(v) for v in value]
    if isinstance(value, dict):
        return {k: encode(v) for k, v in value.items()}
    return value


def _expand(path: str, params: dict[str, str]) -> str:
    out = path
    for name, value in params.items():
        out = out.replace("{*" + name + "}", quote(value, safe="/")).replace("{" + name + "}", quote(value, safe=""))
    if "{" in out:
        raise TypeError("Missing path parameter in " + out)
    return out


class Transport:
    """Sends one request with the configured shop, channel, context and credential."""

    def __init__(self, base_url: str, *, auth: Optional[Auth] = None, tenant: Optional[str] = None,
                 sales_channel: Optional[str] = None, context_token: Optional[str] = None,
                 headers: Optional[dict[str, str]] = None, timeout: float = 30.0):
        self.base_url = base_url.rstrip("/")
        self.auth = auth
        self.tenant = tenant
        self.sales_channel = sales_channel
        self.context_token = context_token
        self.headers = dict(headers or {})
        self.timeout = timeout

    def options(self) -> dict[str, Any]:
        return {"auth": self.auth, "tenant": self.tenant, "sales_channel": self.sales_channel,
                "context_token": self.context_token, "headers": self.headers, "timeout": self.timeout}

    def request(self, method: str, path: str, params: dict[str, str], *, body: Any = None,
                query: Optional[dict[str, Any]] = None, headers: Optional[dict[str, str]] = None) -> Any:
        url = self.base_url + _expand(path, params)
        query = {k: ("true" if v is True else "false" if v is False else v) for k, v in (query or {}).items() if v is not None}
        if query:
            url += "?" + urlencode(query)
        sent = {"Accept": "application/json", **self.headers}
        if self.auth:
            sent["Authorization"] = "Bearer " + self.auth.secret
        if self.tenant:
            sent["x-tenant"] = self.tenant
        if self.sales_channel:
            sent["sw-sales-channel-id"] = self.sales_channel
        if self.context_token:
            sent["sw-context-token"] = self.context_token
        data = None
        if body is not None:
            sent["Content-Type"] = "application/json"
            data = json.dumps(encode(body)).encode()
        sent.update(headers or {})
        try:
            response = urlopen(Request(url, data=data, headers=sent, method=method), timeout=self.timeout)
        except HTTPError as error:
            response = error
        with response:
            raw = response.read().decode()
            kind = response.headers.get("Content-Type") or ""
            value = json.loads(raw) if raw and "json" in kind else (raw or None)
            if response.status >= 400:
                raise VeyndoError(response.status, _problems(value), value)
            return value


def paginate(fetch_page: Callable[[Optional[str]], Any], *, items: str = "elements", max_pages: int = 1000) -> Iterator[Any]:
    """Yields every item of a cursor-paginated read.

    `fetch_page` receives the previous page's `nextCursor` (None first) and passes it as the
    route's cursor field (`after` for catalogue, product and customer lists). Stops when
    `nextCursor` is absent or `hasMore` is false.
    """
    cursor = None
    for _ in range(max_pages):
        page = fetch_page(cursor)
        yield from page.get(items) or []
        cursor = page.get("nextCursor")
        if cursor is None or page.get("hasMore") is False:
            return


class Mcp:
    """JSON-RPC 2.0 calls to `POST /mcp` with the client's shop and credential."""

    def __init__(self, transport: Transport):
        self.transport = transport
        self._ids = itertools.count(1)

    def rpc(self, method: str, params: Any = None) -> Any:
        message: dict[str, Any] = {"jsonrpc": "2.0", "id": next(self._ids), "method": method}
        if params is not None:
            message["params"] = params
        reply = self.transport.request("POST", "/mcp", {}, body=message)
        if reply.get("error"):
            error = reply["error"]
            raise McpProtocolError(error.get("code", 0), error.get("message", ""), error.get("data"))
        return reply.get("result")

    def list_tools(self) -> list[dict[str, Any]]:
        """The tools the current credential may call in the selected shop."""
        return (self.rpc("tools/list") or {}).get("tools", [])

    def call(self, tool: Any, arguments: Any = None) -> Any:
        """Calls a native tool by name with a dict, or with a generated input dataclass alone.

        A tool error becomes a `VeyndoError` with its structured problems.
        """
        if arguments is None and hasattr(tool, "TOOL"):
            tool, arguments = tool.TOOL, tool
        result = self.rpc("tools/call", {"name": tool, "arguments": encode(arguments if arguments is not None else {})}) or {}
        if result.get("isError"):
            problems = _problems(result.get("structuredContent"))
            raise VeyndoError(problems[0].status if problems else 400, problems, result)
        return result.get("structuredContent", result)
